/**
 * Personal API token rows. Lookups by secret go through `tokenHash`; every
 * other read and write is scoped by `orgId`.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

/** Everything the service has already computed: the secret never appears here. */
export interface NewApiToken {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
}

/**
 * Inserts the token only if the user still has fewer than `limit` usable
 * tokens in the org. The count and the insert share one synchronous SQLite
 * transaction, so two concurrent creations cannot both pass the check.
 * Resolves `null` when the limit is already reached.
 */
export async function insertApiTokenWithinLimit(
  input: NewApiToken,
  limit: number,
): Promise<ApiToken | null> {
  return getDb().transaction((tx) => {
    const usable = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, input.orgId),
          eq(apiTokens.userId, input.userId),
          isNull(apiTokens.revokedAt),
          gt(apiTokens.expiresAt, input.createdAt),
        ),
      )
      .get();

    if ((usable?.value ?? 0) >= limit) return null;

    const row = tx
      .insert(apiTokens)
      .values({
        id: newId(),
        orgId: input.orgId,
        userId: input.userId,
        name: input.name,
        scope: input.scope,
        prefix: input.prefix,
        tokenHash: input.tokenHash,
        expiresAt: input.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: input.createdAt,
        updatedAt: input.createdAt,
      })
      .returning()
      .get();

    return toApiToken(row);
  });
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/** Resolves a presented secret. The hash is the lookup key, never a returned field. */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Every token the user holds in the org, revoked and expired included, newest first. */
export async function listApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
      ),
    )
    // `rowid` breaks ties between tokens created in the same millisecond.
    .orderBy(desc(apiTokens.createdAt), desc(sql`rowid`))
    .all();
  return rows.map(toApiToken);
}

/**
 * Sets `revokedAt` on a live token. Resolves `null` when no live token matched,
 * which covers both "not in this org" and "already revoked".
 */
export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * Revokes every live token a user holds in one org — used when they are
 * removed from it. Expired tokens are included; tokens in other orgs are not
 * touched. Returns only the tokens this call actually revoked.
 */
export async function revokeUserApiTokens(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .all();
  return rows.map(toApiToken);
}

export async function touchApiTokenLastUsed(
  tokenId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at })
    .where(eq(apiTokens.id, tokenId))
    .run();
}

