/**
 * Personal API tokens: issue, list, revoke and authenticate the `tfk_` secrets
 * scripts and CI send on a member's behalf.
 *
 * Only a SHA-256 digest of each secret is persisted, so the secret exists in
 * one place: the return value of `createApiToken`. Creations and revocations
 * are announced on the bus, and the audit log records them from there.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken
 */
import { parseIso } from "@/lib/date";
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, envelope, orgResource, requireFound } from "./_support";
import { resolveActor } from "./member-service";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** Every secret starts with this, so a leaked one is recognisable to scanners. */
const SECRET_PREFIX = "tfk_";

/** Random bytes behind the URL-safe part of the secret. */
const SECRET_BYTES = 32;

/** Leading characters of the secret kept on the row and shown in lists. */
const PREFIX_LENGTH = 12;

/** Usable (unrevoked, unexpired) tokens one user may hold per organization. */
const MAX_USABLE_TOKENS = 5;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Raised when the user already holds the maximum number of usable tokens. */
export class ApiTokenLimitError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly limit: number) {
    super(
      `You already have ${limit} active API tokens in this organization; revoke one first.`,
    );
    this.name = "ApiTokenLimitError";
  }
}

/**
 * Issues a token and returns its secret once. `read` tokens are open to every
 * role; `write` tokens need `member` or higher.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:write", orgResource(parsed.orgId));
  }

  const now = new Date();
  const token = `${SECRET_PREFIX}${randomToken(SECRET_BYTES)}`;

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS,
  );
  if (apiToken === null) {
    throw new ApiTokenLimitError(MAX_USABLE_TOKENS);
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    ownerId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

/**
 * A user's tokens in one organization, newest first, revoked and expired ones
 * included. Reading another user's list needs `api_token:manage`.
 */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    assertCan(actor, "api_token:manage", orgResource(orgId));
  }
  return apiTokenRepo.listApiTokensForUser(orgId, userId);
}

/**
 * Revokes a token. Anyone may revoke their own; another user's token needs
 * `api_token:manage`. Revoking an already-revoked token returns it unchanged
 * and records nothing.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const current = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );

  if (current.userId !== actor.userId) {
    assertCan(actor, "api_token:manage", orgResource(orgId));
  }
  if (current.revokedAt !== null) return current;

  const revoked = await apiTokenRepo.revokeApiToken(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );
  if (revoked === null) {
    // Another call revoked it between the read and the write; nothing new to record.
    return requireFound(
      await apiTokenRepo.findApiTokenById(orgId, tokenId),
      "ApiToken",
      tokenId,
    );
  }

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    ownerId: revoked.userId,
    name: revoked.name,
  });

  return revoked;
}

/**
 * Resolves a presented secret to the `Actor` it acts as. Returns `null` when
 * the token is unknown, revoked or expired, or when its owner is no longer an
 * active member of a live organization. A successful call stamps `lastUsedAt`.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  if (!token.startsWith(SECRET_PREFIX)) return null;

  const now = new Date();
  const apiToken = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (apiToken === null || apiToken.revokedAt !== null) return null;
  if (parseIso(apiToken.expiresAt).getTime() <= now.getTime()) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await resolveActor(apiToken.userId, apiToken.orgId);
  if (member === null) return null;

  await apiTokenRepo.touchApiTokenLastUsed(apiToken.id, toIsoTimestamp(now));

  return {
    userId: member.userId,
    orgId: member.orgId,
    // A read token never carries more than viewer rights, whatever the member's role.
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Revokes a departing member's live tokens in that organization. The remover
 * is recorded as the actor on each revocation, not the token's owner.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const revoked = await apiTokenRepo.revokeUserApiTokens(
      payload.orgId,
      payload.userId,
      toIsoTimestamp(new Date()),
    );

    for (const token of revoked) {
      await emit("api_token.revoked", {
        ...envelope(payload.orgId, payload.actorId),
        tokenId: token.id,
        ownerId: token.userId,
        name: token.name,
      });
    }
  });
}

