import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { ZodError } from "zod";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { apiTokens, getDb } from "@/server/db";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as activityService from "@/server/services/activity-service";
import * as apiTokenService from "@/server/services/api-token-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as memberService from "@/server/services/member-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { OrgId, UserId } from "@/types/common";

let cleanup: () => void;
const DAY = 24 * 60 * 60 * 1000;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  vi.useRealTimers();
  cleanup();
});

async function auditRowsFor(orgId: OrgId, subjectId: string, owner: UserId) {
  const page = await activityService.listActivity(
    // owner has activity:read
    { userId: owner, orgId, role: "owner" },
    { orgId, limit: 100, cursor: null, subjectKind: "api_token" },
  );
  return page.items.filter((row) => row.subjectId === subjectId);
}

describe("createApiToken", () => {
  it("returns a tfk_ secret once, stores only its hash, and audits the creation", async () => {
    const t = await createTenant("tok-create");
    const actor = t.actors.member;

    const { token, apiToken } = await apiTokenService.createApiToken(actor, {
      orgId: t.org.id,
      name: "  CI deploy  ",
      scope: "write",
      expiresInDays: 30,
    });

    expect(token).toMatch(/^tfk_[A-Za-z0-9_-]+$/);
    expect(apiToken.prefix).toBe(token.slice(0, 12));
    expect(apiToken.name).toBe("CI deploy");
    expect(apiToken.scope).toBe("write");
    expect(apiToken.userId).toBe(actor.userId);
    expect(apiToken.orgId).toBe(t.org.id);
    expect(apiToken.lastUsedAt).toBeNull();
    expect(apiToken.revokedAt).toBeNull();
    expect(Date.parse(apiToken.expiresAt) - Date.parse(apiToken.createdAt)).toBe(30 * DAY);

    const serialized = JSON.stringify(apiToken);
    expect(serialized).not.toContain(token);
    expect(serialized).not.toContain(hashToken(token));
    expect(Object.keys(apiToken).sort()).toEqual(
      ["createdAt", "expiresAt", "id", "lastUsedAt", "name", "orgId", "prefix", "revokedAt", "scope", "userId"],
    );

    const row = getDb().select().from(apiTokens).where(eq(apiTokens.id, apiToken.id)).get();
    expect(row?.tokenHash).toBe(hashToken(token));
    expect(JSON.stringify(row)).not.toContain(token);

    const audit = await auditRowsFor(t.org.id, apiToken.id, t.userIds.owner);
    expect(audit).toHaveLength(1);
    expect(audit[0]?.action).toBe("api_token.created");
    expect(audit[0]?.actorId).toBe(actor.userId);
    expect(audit[0]?.subjectKind).toBe("api_token");
    expect(JSON.stringify(audit)).not.toContain(token);
    expect(JSON.stringify(audit)).not.toContain(hashToken(token));
  });

  it("rejects invalid input with ZodError and stores nothing", async () => {
    const t = await createTenant("tok-invalid");
    const actor = t.actors.member;
    const before = getDb().select().from(apiTokens).all().length;

    const bad = [
      { name: "   ", scope: "read", expiresInDays: 7 },
      { name: "x".repeat(81), scope: "read", expiresInDays: 7 },
      { name: "ok", scope: "admin", expiresInDays: 7 },
      { name: "ok", scope: "read", expiresInDays: 0 },
      { name: "ok", scope: "read", expiresInDays: 366 },
      { name: "ok", scope: "read", expiresInDays: 1.5 },
    ] as const;

    for (const input of bad) {
      await expect(
        apiTokenService.createApiToken(actor, { orgId: t.org.id, ...input } as never),
      ).rejects.toBeInstanceOf(ZodError);
    }
    expect(getDb().select().from(apiTokens).all().length).toBe(before);
  });

  it("rejects an orgId that is not the actor's organization", async () => {
    const a = await createTenant("tok-scope-a");
    const b = await createTenant("tok-scope-b");

    await expect(
      apiTokenService.createApiToken(a.actors.owner, {
        orgId: b.org.id,
        name: "x",
        scope: "read",
        expiresInDays: 1,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("lets a viewer create read tokens but not write tokens", async () => {
    const t = await createTenant("tok-viewer");
    await expect(
      apiTokenService.createApiToken(t.actors.viewer, {
        orgId: t.org.id,
        name: "read",
        scope: "read",
        expiresInDays: 1,
      }),
    ).resolves.toBeDefined();
    await expect(
      apiTokenService.createApiToken(t.actors.viewer, {
        orgId: t.org.id,
        name: "write",
        scope: "write",
        expiresInDays: 1,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("caps a user at five usable tokens per org, per user", async () => {
    const t = await createTenant("tok-limit");
    const input = (name: string) => ({ orgId: t.org.id, name, scope: "read" as const, expiresInDays: 7 });

    const created = [];
    for (let i = 0; i < 5; i += 1) {
      created.push(await apiTokenService.createApiToken(t.actors.member, input(`t${i}`)));
    }
