async function auditRowsFor(orgId: OrgId, subjectId: string, owner: UserId) {
  const page = await activityService.listActivity(
    // owner has activity:read
    { userId: owner, orgId, role: "owner" },
    { orgId, limit: 100, cursor: null, subjectKind: "api_token" },
  );
  return page.items.filter((row) => row.subjectId === subjectId);
}

