describe("authenticateApiToken", () => {
  it("resolves read tokens to viewer and write tokens to the member's current role", async () => {
    const t = await createTenant("tok-auth-role");
    const readTok = await apiTokenService.createApiToken(t.actors.member, { orgId: t.org.id, name: "r", scope: "read", expiresInDays: 3 });
