import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { ZodError } from "zod";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { apiTokens, getDb } from "@/server/db";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as activityService from "@/server/services/activity-service";
import * as apiTokenService from "@/server/services/api-token-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as memberService from "@/server/services/member-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { OrgId, UserId } from "@/types/common";

let cleanup: () => void;
const DAY = 24 * 60 * 60 * 1000;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  vi.useRealTimers();
  cleanup();
});

async function auditRowsFor(orgId: OrgId, subjectId: string, owner: UserId) {
  const page = await activityService.listActivity(
    // owner has activity:read
    { userId: owner, orgId, role: "owner" },
    { orgId, limit: 100, cursor: null, subjectKind: "api_token" },
  );
  return page.items.filter((row) => row.subjectId === subjectId);
}

describe("createApiToken", () => {
  it("returns a tfk_ secret once, stores only its hash, and audits the creation", async () => {
    const t = await createTenant("tok-create");
    const actor = t.actors.member;

    const { token, apiToken } = await apiTokenService.createApiToken(actor, {
      orgId: t.org.id,
      name: "  CI deploy  ",
      scope: "write",
      expiresInDays: 30,
    });

    expect(token).toMatch(/^tfk_[A-Za-z0-9_-]+$/);
    expect(apiToken.prefix).toBe(token.slice(0, 12));
    expect(apiToken.name).toBe("CI deploy");
    expect(apiToken.scope).toBe("write");
    expect(apiToken.userId).toBe(actor.userId);
    expect(apiToken.orgId).toBe(t.org.id);
    expect(apiToken.lastUsedAt).toBeNull();
    expect(apiToken.revokedAt).toBeNull();
    expect(Date.parse(apiToken.expiresAt) - Date.parse(apiToken.createdAt)).toBe(30 * DAY);

    const serialized = JSON.stringify(apiToken);
    expect(serialized).not.toContain(token);
    expect(serialized).not.toContain(hashToken(token));
    expect(Object.keys(apiToken).sort()).toEqual(
      ["createdAt", "expiresAt", "id", "lastUsedAt", "name", "orgId", "prefix", "revokedAt", "scope", "userId"],
    );

    const row = getDb().select().from(apiTokens).where(eq(apiTokens.id, apiToken.id)).get();
    expect(row?.tokenHash).toBe(hashToken(token));
    expect(JSON.stringify(row)).not.toContain(token);

    const audit = await auditRowsFor(t.org.id, apiToken.id, t.userIds.owner);
    expect(audit).toHaveLength(1);
    expect(audit[0]?.action).toBe("api_token.created");
    expect(audit[0]?.actorId).toBe(actor.userId);
    expect(audit[0]?.subjectKind).toBe("api_token");
    expect(JSON.stringify(audit)).not.toContain(token);
    expect(JSON.stringify(audit)).not.toContain(hashToken(token));
  });

  it("rejects invalid input with ZodError and stores nothing", async () => {
    const t = await createTenant("tok-invalid");
    const actor = t.actors.member;
    const before = getDb().select().from(apiTokens).all().length;

    const bad = [
      { name: "   ", scope: "read", expiresInDays: 7 },
      { name: "x".repeat(81), scope: "read", expiresInDays: 7 },
      { name: "ok", scope: "admin", expiresInDays: 7 },
      { name: "ok", scope: "read", expiresInDays: 0 },
      { name: "ok", scope: "read", expiresInDays: 366 },
      { name: "ok", scope: "read", expiresInDays: 1.5 },
    ] as const;

    for (const input of bad) {
      await expect(
        apiTokenService.createApiToken(actor, { orgId: t.org.id, ...input } as never),
      ).rejects.toBeInstanceOf(ZodError);
    }
    expect(getDb().select().from(apiTokens).all().length).toBe(before);
  });

  it("rejects an orgId that is not the actor's organization", async () => {
    const a = await createTenant("tok-scope-a");
    const b = await createTenant("tok-scope-b");

    await expect(
      apiTokenService.createApiToken(a.actors.owner, {
        orgId: b.org.id,
        name: "x",
        scope: "read",
        expiresInDays: 1,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("lets a viewer create read tokens but not write tokens", async () => {
    const t = await createTenant("tok-viewer");
    await expect(
      apiTokenService.createApiToken(t.actors.viewer, {
        orgId: t.org.id,
        name: "read",
        scope: "read",
        expiresInDays: 1,
      }),
    ).resolves.toBeDefined();
    await expect(
      apiTokenService.createApiToken(t.actors.viewer, {
        orgId: t.org.id,
        name: "write",
        scope: "write",
        expiresInDays: 1,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("caps a user at five usable tokens per org, per user", async () => {
    const t = await createTenant("tok-limit");
    const input = (name: string) => ({ orgId: t.org.id, name, scope: "read" as const, expiresInDays: 7 });

    const created = [];
    for (let i = 0; i < 5; i += 1) {
      created.push(await apiTokenService.createApiToken(t.actors.member, input(`t${i}`)));
    }
    await expect(apiTokenService.createApiToken(t.actors.member, input("sixth"))).rejects.toThrow();

    const rows = getDb().select().from(apiTokens).where(eq(apiTokens.userId, t.userIds.member)).all();
    expect(rows).toHaveLength(5);

    // Another user in the same org has their own allowance.
    await expect(apiTokenService.createApiToken(t.actors.admin, input("admin-1"))).resolves.toBeDefined();

    // Revoking one frees a slot.
    const [first] = created;
    if (!first) throw new Error("expected a first token");
    await apiTokenService.revokeApiToken(t.actors.member, t.org.id, first.apiToken.id);
    await expect(apiTokenService.createApiToken(t.actors.member, input("replacement"))).resolves.toBeDefined();
  });

  it("does not count expired tokens against the cap", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date("2026-06-01T12:00:00.000Z"));
      const t = await createTenant("tok-expiry-cap");
      for (let i = 0; i < 5; i += 1) {
        await apiTokenService.createApiToken(t.actors.member, {
          orgId: t.org.id,
          name: `d${i}`,
          scope: "read",
          expiresInDays: 1,
        });
      }
      vi.setSystemTime(new Date("2026-06-02T12:00:00.000Z"));
      await expect(
        apiTokenService.createApiToken(t.actors.member, {
          orgId: t.org.id,
          name: "after-expiry",
          scope: "read",
          expiresInDays: 1,
        }),
      ).resolves.toBeDefined();
    } finally {
      vi.useRealTimers();
    }
  });
});

describe("listApiTokens", () => {
  it("returns the user's tokens newest first, including revoked and expired ones", async () => {
    const t = await createTenant("tok-list");
    const m = t.actors.member;
    const orgId = t.org.id;

    const a = await apiTokenService.createApiToken(m, { orgId, name: "a", scope: "read", expiresInDays: 1 });
    const b = await apiTokenService.createApiToken(m, { orgId, name: "b", scope: "write", expiresInDays: 30 });
    await apiTokenService.revokeApiToken(m, orgId, a.apiToken.id);
    const c = await apiTokenService.createApiToken(m, { orgId, name: "c", scope: "read", expiresInDays: 30 });

    const list = await apiTokenService.listApiTokens(m, orgId);
    expect(list.map((tok) => tok.id)).toEqual([c.apiToken.id, b.apiToken.id, a.apiToken.id]);
    expect(list[2]?.revokedAt).not.toBeNull();
  });

  it("returns the caller's own tokens without any role, but needs api_token:manage for someone else's", async () => {
    const t = await createTenant("tok-list-others");
    await apiTokenService.createApiToken(t.actors.member, {
      orgId: t.org.id,
      name: "m",
      scope: "read",
      expiresInDays: 1,
    });

    await expect(
      apiTokenService.listApiTokens(t.actors.member, t.org.id, t.userIds.owner),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      apiTokenService.listApiTokens(t.actors.viewer, t.org.id, t.userIds.member),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const asAdmin = await apiTokenService.listApiTokens(t.actors.admin, t.org.id, t.userIds.member);
    expect(asAdmin).toHaveLength(1);

    const own = await apiTokenService.listApiTokens(t.actors.viewer, t.org.id);
    expect(own).toHaveLength(0);
  });

  it("rejects another organization's orgId with a tenant-scope error", async () => {
    const a = await createTenant("tok-list-a");
    const b = await createTenant("tok-list-b");
    await expect(apiTokenService.listApiTokens(a.actors.owner, b.org.id)).rejects.toBeInstanceOf(
      TenantScopeError,
    );
  });
});

describe("revokeApiToken", () => {
  it("lets owners revoke their own, admins revoke others', and no one else revoke others'", async () => {
    const t = await createTenant("tok-revoke");
    const orgId = t.org.id;
    const mine = await apiTokenService.createApiToken(t.actors.member, { orgId, name: "m", scope: "read", expiresInDays: 9 });
    const theirs = await apiTokenService.createApiToken(t.actors.admin, { orgId, name: "a", scope: "read", expiresInDays: 9 });

    await expect(apiTokenService.revokeApiToken(t.actors.member, orgId, theirs.apiToken.id)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );

    const revokedOwn = await apiTokenService.revokeApiToken(t.actors.member, orgId, mine.apiToken.id);
    expect(revokedOwn.revokedAt).not.toBeNull();

    const revokedByAdmin = await apiTokenService.revokeApiToken(t.actors.admin, orgId, mine.apiToken.id).catch(() => null);
    // Already revoked: returned unchanged, not an error.
    expect(revokedByAdmin?.revokedAt).toBe(revokedOwn.revokedAt);

    const adminRevokesMember = await apiTokenService.revokeApiToken(t.actors.admin, orgId, mine.apiToken.id);
    expect(adminRevokesMember.revokedAt).toBe(revokedOwn.revokedAt);

    const other = await apiTokenService.revokeApiToken(t.actors.owner, orgId, theirs.apiToken.id);
    expect(other.revokedAt).not.toBeNull();

    const audit = await auditRowsFor(orgId, mine.apiToken.id, t.userIds.owner);
    expect(audit.filter((row) => row.action === "api_token.revoked")).toHaveLength(1);
    expect(audit.find((row) => row.action === "api_token.revoked")?.actorId).toBe(t.userIds.member);

    const auditTheirs = await auditRowsFor(orgId, theirs.apiToken.id, t.userIds.owner);
    expect(auditTheirs.find((row) => row.action === "api_token.revoked")?.actorId).toBe(t.userIds.owner);
  });

  it("reports a missing token, including one that lives in another organization, as not found", async () => {
    const a = await createTenant("tok-revoke-nf-a");
    const b = await createTenant("tok-revoke-nf-b");
    const inB = await apiTokenService.createApiToken(b.actors.owner, {
      orgId: b.org.id,
      name: "b",
      scope: "read",
      expiresInDays: 2,
    });

    await expect(
      apiTokenService.revokeApiToken(a.actors.owner, a.org.id, "01HZZZNOPE0000000000000000"),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      apiTokenService.revokeApiToken(a.actors.owner, a.org.id, inB.apiToken.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

