    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date("2026-07-01T00:00:00.000Z"));
      const t = await createTenant("tok-auth-expiry");
      const made = await apiTokenService.createApiToken(t.actors.member, { orgId: t.org.id, name: "e", scope: "read", expiresInDays: 1 });

      vi.setSystemTime(new Date("2026-07-01T23:59:59.999Z"));
      expect(await apiTokenService.authenticateApiToken(made.token)).not.toBeNull();

      vi.setSystemTime(new Date("2026-07-02T00:00:00.000Z"));
      expect(await apiTokenService.authenticateApiToken(made.token)).toBeNull();
    } finally {
      vi.useRealTimers();
    }
  });
});

describe("member removal", () => {
  it("revokes the removed member's live tokens in that org only, audited with the remover as actor", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date("2026-08-01T00:00:00.000Z"));
      const t = await createTenant("tok-cascade-a");
      const other = await createTenant("tok-cascade-b");
      const orgA = t.org.id;
      const member = t.actors.member;

      // The same user also belongs to the other org.
      await memberRepo.insertMember(other.org.id, t.userIds.member, "member", null);
      const otherActor = { userId: t.userIds.member, orgId: other.org.id, role: "member" as const };

      const live = await apiTokenService.createApiToken(member, { orgId: orgA, name: "live", scope: "write", expiresInDays: 30 });
      const pre = await apiTokenService.createApiToken(member, { orgId: orgA, name: "pre", scope: "read", expiresInDays: 30 });
      await apiTokenService.revokeApiToken(member, orgA, pre.apiToken.id);
      const preRevokedAt = (await apiTokenService.listApiTokens(member, orgA)).find((tok) => tok.id === pre.apiToken.id)?.revokedAt;

      // Expires before removal, but still gets revoked.
      const expiring = await apiTokenService.createApiToken(member, { orgId: orgA, name: "expiring", scope: "read", expiresInDays: 1 });
      const elsewhere = await apiTokenService.createApiToken(otherActor, { orgId: other.org.id, name: "elsewhere", scope: "read", expiresInDays: 30 });

      vi.setSystemTime(new Date("2026-08-05T00:00:00.000Z"));
      const memberRow = await memberRepo.findMember(orgA, t.userIds.member);
      if (!memberRow) throw new Error("fixture member missing");
      await memberService.removeMember(t.actors.owner, { orgId: orgA, memberId: memberRow.id });

      const listed = await apiTokenService.listApiTokens(member, orgA);
      const byId = new Map(listed.map((tok) => [tok.id, tok]));
      expect(byId.get(live.apiToken.id)?.revokedAt).not.toBeNull();
      expect(byId.get(expiring.apiToken.id)?.revokedAt).not.toBeNull();
      expect(byId.get(pre.apiToken.id)?.revokedAt).toBe(preRevokedAt);

      const liveAudit = await auditRowsFor(orgA, live.apiToken.id, t.userIds.owner);
      const liveRevoked = liveAudit.filter((row) => row.action === "api_token.revoked");
      expect(liveRevoked).toHaveLength(1);
      expect(liveRevoked[0]?.actorId).toBe(t.userIds.owner);

      const preAudit = await auditRowsFor(orgA, pre.apiToken.id, t.userIds.owner);
      expect(preAudit.filter((row) => row.action === "api_token.revoked")).toHaveLength(1);

      const elsewhereTokens = await apiTokenService.listApiTokens(otherActor, other.org.id);
      expect(elsewhereTokens.find((tok) => tok.id === elsewhere.apiToken.id)?.revokedAt).toBeNull();

      expect(await apiTokenService.authenticateApiToken(live.token)).toBeNull();
      expect(await apiTokenService.authenticateApiToken(elsewhere.token)).not.toBeNull();
    } finally {
      vi.useRealTimers();
    }
  });
});
